-- light-mes 增量面板注册（2026-08-25）：仅 panel_config，不触碰 form_data 业务数据
DELETE FROM panel_config WHERE panel_code IN ('PU_REQ', 'PU_REQ_ANALYSIS', 'TRANSFER', 'OUTSOURCE_ORDER', 'OUTSOURCE_ISSUE', 'OUTSOURCE_IN', 'OUTSOURCE_FEE', 'QUOTE_ORDER', 'SALE_INVOICE', 'EXPENSE', 'SALE_COST_ALLOC', 'PU_INVOICE', 'PU_COST_ALLOC', 'STOCK_CHECK', 'LOCATION_ADJUST', 'SERIAL_NO', 'SERIAL_STATUS', 'SERIAL_TRACE');
